const waData = $('WhatsApp Inicio').first().json;
const ref = $input.first().json;

let analysis = {};
try { analysis = JSON.parse(ref.ad_image_analysis || '{}'); } catch(e) {}

return [{
  json: {
    ...waData,
    _es_desde_anuncio: !!(ref.ctwa_clid),
    _referral_headline: ref.headline || '',
    _referral_body: ref.body || '',
    _referral_source_url: ref.source_url || '',
    _referral_media_url: ref.image_url || '',
    _referral_ctwa_clid: ref.ctwa_clid || '',
    _referral_ad_id: ref.ad_id || '',
    _referral_service_type: ref.service_type_inferred || '',
    _referral_producto: analysis.producto_principal || '',
    _referral_precio_visible: analysis.precio_visible || '',
    _referral_cta: analysis.cta_observado || '',
    _referral_estilo: analysis.estilo || '',
  }
}];

// Parser robusto del output JSON del Agente Laundry VIP
// Tolerante a: comillas curvas, BOM, fences ```json, múltiples JSON pegados, NBSP

const rawOutput = $('Agente Laundry VIP').first().json.output || '';
const waInicio = $('WhatsApp Inicio').first().json;

function tryParseLLMOutput(s) {
  if (typeof s !== 'string') return s;
  let t = s
    .replace(/^\uFEFF/, '')                          // BOM
    .replace(/^\s*```(?:json)?\s*/i, '')             // fence apertura
    .replace(/\s*```\s*$/i, '')                      // fence cierre
    .replace(/[\u201C\u201D]/g, '"')                 // comillas curvas dobles -> "
    .replace(/[\u2018\u2019]/g, "'")                 // comillas curvas simples -> '
    .replace(/\u00A0/g, ' ');                        // nbsp -> espacio
  // Si hay multiples JSON pegados, quedate con el primer objeto balanceado
  const start = t.indexOf('{');
  if (start === -1) throw new Error('no JSON found');
  let depth = 0, end = -1, inStr = false, esc = false;
  for (let i = start; i < t.length; i++) {
    const c = t[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
    } else {
      if (c === '"') inStr = true;
      else if (c === '{') depth++;
      else if (c === '}') { depth--; if (depth === 0) { end = i; break; } }
    }
  }
  if (end === -1) throw new Error('unbalanced JSON');
  return JSON.parse(t.slice(start, end + 1));
}

let parsed = {};
let parseFailed = false;
try {
  parsed = typeof rawOutput === 'string' ? tryParseLLMOutput(rawOutput) : rawOutput;
} catch(e) {
  // Fallback FINAL: NUNCA mandar JSON crudo. Mensaje de cortesia + escalar humano.
  parseFailed = true;
  parsed = {
    respuesta_lead: 'Permítame un momento, le contacta una persona de nuestro equipo.',
    tool_consultada: null,
    imagenes: [],
    videos: [],
    ubicacion: false,
    escalar_humano: true,
    metadata: {
      temperatura: 'tibio',
      pain_point: 'parser fallo, escalar a humano',
      objeciones: [],
      next_action: 'esperar_respuesta',
      quality_score: 0,
      tipo_lead: 'otro',
      datos_lead: {}
    }
  };
}

const imagenes = Array.isArray(parsed.imagenes) ? parsed.imagenes : [];
const videos = Array.isArray(parsed.videos) ? parsed.videos : [];
const metadata = parsed.metadata || {};
const datosLead = metadata.datos_lead || {};

return [{
  json: {
    // Texto limpio que se enviara al lead (sin metadata, sin markers)
    texto_limpio: parsed.respuesta_lead || '',

    // Imagenes (hasta 5) para los nodos Enviar Img 1-5
    img1: imagenes[0] || '',
    img2: imagenes[1] || '',
    img3: imagenes[2] || '',
    img4: imagenes[3] || '',
    img5: imagenes[4] || '',

    // Videos (hasta 2) para los nodos Enviar Video
    vid1: videos[0] || '',
    vid2: videos[1] || '',

    // Markers de comportamiento
    ubicacion: parsed.ubicacion === true ? 'si' : '',
    escalar_humano: parsed.escalar_humano === true ? 'si' : '',

    // Datos del flow (no cambian)
    phone: waInicio.contacts[0].wa_id,
    conv_id: waInicio._chatwoot_conversation_id,

    // Flag de parser para diagnostico
    parser_failed: parseFailed,

    // Metadata para CRM / logging
    metadata_temperatura: metadata.temperatura || 'frio',
    metadata_pain_point: metadata.pain_point || '',
    metadata_objeciones: Array.isArray(metadata.objeciones) ? metadata.objeciones.join(', ') : '',
    metadata_next_action: metadata.next_action || 'esperar_respuesta',
    metadata_quality_score: metadata.quality_score || 0,
    metadata_tipo_lead: metadata.tipo_lead || 'otro',
    metadata_tool_consultada: parsed.tool_consultada || null,

    // Datos del lead (estructurados)
    lead_nombre: datosLead.nombre || null,
    lead_servicio: datosLead.servicio || null,
    lead_ubicacion: datosLead.ubicacion || null,
    lead_metros: datosLead.metros || null,
    lead_nivel_acabado: datosLead.nivel_acabado || null,
    lead_presupuesto_usd: datosLead.presupuesto_usd || null,
    lead_timeline: datosLead.timeline || null,
    lead_tiene_terreno: datosLead.tiene_terreno || null,

    // Cotizacion (mantenido por compatibilidad - vacio por ahora)
    cotizacion_json: ''
  }
}];
